from typing import List

class Solution:
    def occurrencesOfElement(self, nums: List[int], queries: List[int], x: int) -> List[int]:
        indices = []
        for i, num in enumerate(nums):
            if num == x:
                indices.append(i)
        res = []
        for q in queries:
            if q <= len(indices):
                res.append(indices[q-1])
            else:
                res.append(-1)
        return res

