def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    M = int(input[idx])
    idx += 1

    # Initialize reachability matrix
    reach = [[False] * (N + 1) for _ in range(N + 1)]

    for _ in range(M):
        a = int(input[idx])
        idx += 1
        b = int(input[idx])
        idx += 1
        reach[a][b] = True

    # Floyd-Warshall to compute transitive closure
    for k in range(1, N + 1):
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                if reach[i][k] and reach[k][j]:
                    if not reach[i][j]:
                        reach[i][j] = True

    # Determine candidates for strongest programmer
    candidates = []
    for x in range(1, N + 1):
        is_candidate = True
        for y in range(1, N + 1):
            if y == x:
                continue
            if reach[y][x]:
                is_candidate = False
                break
        if is_candidate:
            candidates.append(x)

    if len(candidates) == 1:
        print(candidates[0])
    else:
        print(-1)

