    N = int(sys.stdin.readline())
    bags = []
    for _ in range(N):
        parts = sys.stdin.readline().split()
        A_i = int(parts[0])
        strings = parts[1:]
        bags.append(strings)

    INF = float('inf')
    dp = [[INF] * (len_T + 1) for _ in range(N + 1)]
    dp[0][0] = 0

    for i in range(1, N + 1):
        for j in range(len_T + 1):
            if dp[i-1][j] != INF:
                # Do nothing
                if dp[i][j] > dp[i-1][j]:
                    dp[i][j] = dp[i-1][j]
                # Take a string from the current bag
                for s in bags[i-1]:
                    l = len(s)
                    if j + l <= len_T:
                        if T[j:j+l] == s:
                            if dp[i][j + l] > dp[i-1][j] + 1:
                                dp[i][j + l] = dp[i-1][j] + 1

    result = dp[N][len_T]
    print(result if result != INF else -1)

